import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        long[] a = new long[n], b = new long[n], c = new long[m], e = new long[m];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        for (int i = 0; i < n; i++) b[i] = nextLong();
        for (int i = 0; i < m; i++) c[i] = nextLong();
        for (int i = 0; i < m; i++) e[i] = nextLong();
        long first = Long.MAX_VALUE, second = Long.MAX_VALUE;
        for (int i = 0; i < n; i++) first = Math.min(first, a[i] + b[i]);
        for (int i = 0; i < m; i++) second = Math.min(second, c[i] + e[i]);
        // Watch the earliest-finishing movie of one genre first, then pick the best of the other.
        long answer = Long.MAX_VALUE;
        for (int i = 0; i < m; i++) answer = Math.min(answer, Math.max(first, c[i]) + e[i]);
        for (int i = 0; i < n; i++) answer = Math.min(answer, Math.max(second, a[i]) + b[i]);
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"math"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, m := int(nextInt()), int(nextInt())
	read := func(k int) []int64 {
		v := make([]int64, k)
		for i := range v {
			v[i] = nextInt()
		}
		return v
	}
	a, b, c, e := read(n), read(n), read(m), read(m)
	first, second := int64(math.MaxInt64), int64(math.MaxInt64)
	for i := 0; i < n; i++ {
		first = min(first, a[i]+b[i])
	}
	for i := 0; i < m; i++ {
		second = min(second, c[i]+e[i])
	}
	// Watch the earliest-finishing movie of one genre first, then pick the best of the other.
	answer := int64(math.MaxInt64)
	for i := 0; i < m; i++ {
		answer = min(answer, max(first, c[i])+e[i])
	}
	for i := 0; i < n; i++ {
		answer = min(answer, max(second, a[i])+b[i])
	}
	fmt.Println(answer)
}
